import { FOOD_TEST_READ_ON, FOOD_TEST_ROWS, FOOD_TEST_SUMMARY, type FoodTestRow } from "@/data/foodDatabaseTest";
import { formatDate } from "@/lib/posts";

/**
 * "The food-database test" on /fitness-apis/nutrition-apis: the same 50
 * generic foods in USDA FoodData Central and Open Food Facts, per 100 g.
 *
 * Every value comes from src/data/foodDatabaseTest.ts, generated by
 * scripts/fetch-food-test.mjs; nothing is typed here. The sentences that
 * carry numbers are built from FOOD_TEST_SUMMARY, so they change when a
 * regeneration does.
 *
 * Open Food Facts data is under the Open Database License, so the section
 * carries the ODbL notice and links the database, and the downloads it
 * offers (public/food-test/) are ODbL too.
 *
 * English only: ClusterPage renders it behind `!tr`, outside the entry body.
 */

export const FOOD_TEST_PATH = "/fitness-apis/nutrition-apis";

const ODBL = "https://opendatacommons.org/licenses/odbl/1-0/";
const OFF = "https://openfoodfacts.org";
const OFF_PRODUCT = "https://world.openfoodfacts.org/product/";
const FILES = "/food-test/food-database-test-2026";

const pct = (x: number | null) => (x === null ? "n/a" : `${x > 0 ? "+" : ""}${x.toFixed(1)}%`);
const v = (x: number | null, d = 1) => (x === null ? "n/a" : x.toFixed(d).replace(/\.0+$/, ""));
const names = (list: string[]) => (list.length <= 1 ? list.join("") : `${list.slice(0, -1).join(", ")} and ${list[list.length - 1]}`);

function gapLine(r: FoodTestRow) {
  return (
    <li key={r.id}>
      <strong className="text-[var(--fg)]">{r.label}</strong>: USDA {v(r.usda.values.energyKcal)} kcal, Open Food Facts median{" "}
      {v(r.off.median?.energyKcal ?? null)} kcal ({pct(r.diffPct.energyKcal)}) across {r.off.productsCounted} product
      {r.off.productsCounted === 1 ? "" : "s"}, from {v(r.off.range?.energyKcal[0] ?? null)} to{" "}
      {v(r.off.range?.energyKcal[1] ?? null)} kcal.
      {r.off.products.length > 0 && (
        <>
          {" "}The products counted, kcal per 100 g:{" "}
          {r.off.products.map((p, i) => (
            <span key={p.code}>
              {i > 0 ? "; " : ""}
              <a href={`${OFF_PRODUCT}${p.code}`} className="text-brand-600 hover:text-brand-500">
                {p.name ?? `barcode ${p.code}`}
              </a>{" "}
              {v(p.values.energyKcal)}
              {p.per === "100ml" ? " (per 100 ml)" : ""}
            </span>
          ))}
          .
        </>
      )}
    </li>
  );
}

export default function FoodDatabaseTest({ path }: { path: string }) {
  if (path !== FOOD_TEST_PATH) return null;
  const s = FOOD_TEST_SUMMARY;
  const date = formatDate(FOOD_TEST_READ_ON);
  const byId = new Map(FOOD_TEST_ROWS.map((r) => [r.id, r]));
  const gaps = s.biggestEnergyGaps.map((id) => byId.get(id)).filter((r): r is FoodTestRow => Boolean(r));
  const unmatched = s.unmatched.map((id) => byId.get(id)?.label ?? id);
  const dataTypes = Object.entries(s.usdaDataTypes).map(([t, n]) => `${n} ${t}`);
  const energyName = (n: string) => FOOD_TEST_ROWS.find((r) => r.usda.energyNutrient.number === n)?.usda.energyNutrient.name ?? n;
  const energyUse = Object.entries(s.usdaEnergyNutrients)
    .map(([n, c]) => `${c} records use ${n}, ${energyName(n)}`)
    .join("; ");
  const countries = names(s.offTopCountries.map((c) => `${c.country.replace(/^en:/, "").replace(/-/g, " ")} (${c.products})`));

  return (
    <section
      id="food-database-test"
      data-food-database-test
      className="mt-12 scroll-mt-24 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-5 sm:p-6"
    >
      <h2 className="text-lg font-bold tracking-tight text-[var(--fg)]">The food-database test: 50 foods in USDA and Open Food Facts</h2>
      <p className="mt-2 text-sm leading-relaxed text-[var(--muted)]">
        We looked up the same {s.foods} generic foods in the two free databases above, read {date}, and compared
        energy, protein, fat and carbohydrate per 100 g. {s.matched} foods had an Open Food Facts value to compare.
        Across them, the median gap from USDA was {v(s.medianAbsPct.energyKcal)}% for energy,{" "}
        {v(s.medianAbsPct.protein)}% for protein, {v(s.medianAbsPct.fat)}% for fat and{" "}
        {v(s.medianAbsPct.carbohydrate)}% for carbohydrate. Energy agreed within 10% for {s.within10PctEnergy} foods
        and was more than 25% apart for {s.over25PctEnergy}.
        {unmatched.length > 0 && <> No Open Food Facts product with all four values came back for {names(unmatched)}.</>}
      </p>

      <h3 className="mt-5 text-sm font-semibold text-[var(--fg)]">How each food was matched</h3>
      <ul className="mt-2 list-disc space-y-1.5 pl-5 text-sm leading-relaxed text-[var(--muted)]">
        <li>
          <strong className="text-[var(--fg)]">USDA FoodData Central:</strong>{" "}
          one record per food, picked by hand and pinned by its fdcId ({names(dataTypes)} records): Foundation
          Foods where it has the food with all four values, SR Legacy otherwise, and where Foundation lists only
          named varieties, one variety, named in the table. The generator fails if a pinned record disappears or
          changes its description.
        </li>
        <li>
          <strong className="text-[var(--fg)]">Open Food Facts:</strong>{" "}
          the food&rsquo;s category in Open Food Facts&rsquo; taxonomy, and the first 10 products its search returns
          for that category when asked to sort by{" "}
          <code className="font-mono text-xs">unique_scans_n</code>, which its API reference lists among the
          popularity sorts. A product counts when it states all four values per 100 g; the food&rsquo;s value is the
          median of those products ({s.offProductsCounted} products in all).
        </li>
        <li>
          <strong className="text-[var(--fg)]">The bias:</strong>{" "}
          Open Food Facts is crowd-sourced and mostly packaged food, so a category holds what contributors filed
          there, including branded, dried or prepared versions and plain mistakes. The countries most often tagged
          on the counted products are {countries}, and {s.offPer100ml} of them state their values per 100 ml rather
          than per 100 g. A USDA record describes one generic food. So a large gap can mean the two databases describe
          different things under one name (look at the products behind the biggest gaps below), and that is the
          point of the test: a food-logging app that falls back from one source to the other changes the numbers its
          users see.
        </li>
      </ul>

      {gaps.length > 0 && (
        <>
          <h3 className="mt-5 text-sm font-semibold text-[var(--fg)]">The biggest energy gaps</h3>
          <ul className="mt-2 list-disc space-y-1.5 pl-5 text-sm leading-relaxed text-[var(--muted)]">{gaps.map(gapLine)}</ul>
        </>
      )}

      <div className="mt-5 overflow-x-auto">
        <table className="w-full min-w-[640px] text-left text-xs">
          <thead className="uppercase tracking-wider text-[var(--muted)]">
            <tr>
              <th className="py-2 pr-3">Food (USDA record)</th>
              <th className="py-2 pr-3 text-right">kcal USDA / OFF</th>
              <th className="py-2 pr-3 text-right">Protein g</th>
              <th className="py-2 pr-3 text-right">Fat g</th>
              <th className="py-2 pr-3 text-right">Carbs g</th>
              <th className="py-2 text-right">OFF products</th>
            </tr>
          </thead>
          <tbody>
            {FOOD_TEST_ROWS.map((r) => (
              <tr key={r.id} id={`food-${r.id}`} className="border-t border-[var(--border)] align-top text-[var(--fg)]">
                <td className="py-2 pr-3">
                  {r.label}
                  <span className="block text-[11px] text-[var(--muted)]">
                    {r.usda.description} · {r.usda.dataType} · fdcId {r.usda.fdcId}
                  </span>
                </td>
                {(["energyKcal", "protein", "fat", "carbohydrate"] as const).map((k) => (
                  <td key={k} className="py-2 pr-3 text-right font-mono">
                    {v(r.usda.values[k], k === "energyKcal" ? 0 : 1)} / {r.off.median ? v(r.off.median[k], k === "energyKcal" ? 0 : 1) : "n/a"}
                    <span className="block text-[11px] text-[var(--muted)]">{pct(r.diffPct[k])}</span>
                  </td>
                ))}
                <td className="py-2 text-right font-mono">{r.off.productsCounted}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="mt-2 text-xs text-[var(--muted)]">
        Each cell is USDA / Open Food Facts median per 100 g, with the Open Food Facts difference from USDA below it.
        USDA energy is nutrient 208 where the record has it, else the Atwater energy the record carries (
        {energyUse}). A percentage on a nutrient the food barely has, such as fat in fruit or carbohydrate in
        cheese, swings widely even when the grams are small, so read it beside the grams.
      </p>

      <h3 className="mt-5 text-sm font-semibold text-[var(--fg)]">What is not in the test</h3>
      <p className="mt-2 text-sm leading-relaxed text-[var(--muted)]">
        Edamam, Nutritionix and Spoonacular are not included: this test uses only the two free databases, and the
        paid APIs would be queried with accounts and keys the site&rsquo;s owner holds. Open Food Facts needs no key
        to read, and USDA documents a
        shared <code className="font-mono text-xs">DEMO_KEY</code> for initial exploration, which is what the
        generator uses unless it is given a key of its own. These are database values for building software, not
        dietary advice.
      </p>

      <div className="mt-5 rounded-xl border border-[var(--border)] p-4 text-xs leading-relaxed text-[var(--muted)]" data-food-test-license>
        <p>
          Contains information from{" "}
          <a href={OFF} className="text-brand-600 hover:text-brand-500">
            Open Food Facts
          </a>
          , which is made available here under the{" "}
          <a href={ODBL} rel="license noopener" className="text-brand-600 hover:text-brand-500">
            Open Database License (ODbL)
          </a>
          . USDA values: U.S. Department of Agriculture, Agricultural Research Service, FoodData Central, public
          domain (CC0 1.0). The downloads below hold Open Food Facts data and are published under the ODbL 1.0.
        </p>
        <p className="mt-3 flex flex-wrap gap-3 text-sm">
          <a href={`${FILES}.json`} data-cta="food-test-json" data-cta-source="nutrition-apis-food-test" className="font-semibold text-brand-600 hover:text-brand-500">
            food-database-test-2026.json
          </a>
          <a href={`${FILES}.csv`} data-cta="food-test-csv" data-cta-source="nutrition-apis-food-test" className="font-semibold text-brand-600 hover:text-brand-500">
            food-database-test-2026.csv
          </a>
          <a href={`${FILES}.md`} className="text-brand-600 hover:text-brand-500">
            how it was built
          </a>
        </p>
      </div>
    </section>
  );
}
